//! `upt completions` — print a shell completion script for `upt`.
//!
//! The script is generated by `clap_complete` from a clap description of the
//! whole command line: `upt`'s own global options, plus each built-in's
//! [`Builtin::command`](crate::commands::Builtin::command) as a subcommand.
//! The clap-based built-ins hand over their real parser definitions; the
//! hand-parsed ones (`help`, `which`, and the drop-in replacements) provide an
//! equivalent clap description that exists only for this purpose.
//!
//! It runs before `upt` loads its config (see `main::run`), so it needs no
//! configuration, credentials, network access or CPAN index, and never writes
//! the starter config file. Only the script is written to stdout.

use std::ffi::OsString;
use std::io::Write as _;

use anyhow::{Context, Result};
use clap::{Arg, ArgAction, Command, Parser, ValueHint};
use clap_complete::Shell;

use crate::Cx;
use crate::commands;

/// Print a shell completion script for upt.
#[derive(Debug, Parser)]
#[command(
    name = "upt completions",
    about = "Print a shell completion script for upt",
    long_about = None,
    after_help = "\
Install, for example:
    zsh         upt completions zsh > ~/.zfunc/_upt
                (with `fpath+=~/.zfunc` before `compinit` in ~/.zshrc)
    bash        upt completions bash > ~/.local/share/bash-completion/completions/upt
    fish        upt completions fish > ~/.config/fish/completions/upt.fish
    powershell  upt completions powershell >> $PROFILE
    elvish      upt completions elvish >> ~/.config/elvish/rc.elv",
)]
struct Cli {
    /// The shell to generate the script for.
    #[arg(value_enum)]
    shell: Shell,
}

/// The `completions` command line, for its own completion.
pub fn command() -> Command {
    <Cli as clap::CommandFactory>::command().name("completions")
}

/// The [`Builtin::run`](crate::commands::Builtin::run) entry point. `main`
/// dispatches `upt completions` to [`run_standalone`] before building a
/// [`Cx`], so this is only reached through `upt help completions`.
pub fn run(_cx: &Cx, args: &[String]) -> Result<i32> {
    run_standalone(args)
}

/// Parse `args` and print the requested script; needs no [`Cx`].
pub fn run_standalone(args: &[String]) -> Result<i32> {
    let argv =
        std::iter::once(OsString::from("upt completions")).chain(args.iter().map(OsString::from));
    let cli = match Cli::try_parse_from(argv) {
        Ok(cli) => cli,
        // clap prints `--help` and usage errors itself; mirror its own exit
        // codes (0 for help, 2 for a usage error).
        Err(err) => {
            err.print().ok();
            return Ok(err.exit_code());
        }
    };

    let mut stdout = std::io::stdout().lock();
    stdout
        .write_all(&script(cli.shell))
        .and_then(|()| stdout.flush())
        .context("writing the completion script")?;
    Ok(0)
}

/// The completion script for `shell`.
pub fn script(shell: Shell) -> Vec<u8> {
    let mut command = cli_command();
    let mut out = Vec::new();
    clap_complete::generate(shell, &mut command, "upt", &mut out);
    if shell == Shell::Fish {
        out.extend_from_slice(fish_positional_values(&command).as_bytes());
    }
    out
}

/// Fish completions for positional arguments with a fixed set of values, such
/// as `upt completions <SHELL>`, which `clap_complete`'s fish generator leaves
/// out (it only lists the values of options).
fn fish_positional_values(command: &Command) -> String {
    let mut out = String::new();
    fish_collect(command, &mut Vec::new(), &mut out);
    if out.is_empty() {
        return out;
    }
    format!("\n# Enumerated positional arguments.\n{out}")
}

fn fish_collect<'a>(command: &'a Command, path: &mut Vec<&'a str>, out: &mut String) {
    let values: Vec<String> = command
        .get_positionals()
        .flat_map(|arg| arg.get_possible_values())
        .filter(|value| !value.is_hide_set())
        .map(|value| value.get_name().to_string())
        .collect();
    if !values.is_empty() {
        let condition = match path.as_slice() {
            [] => "__fish_upt_needs_command".to_string(),
            [first, rest @ ..] => {
                let mut condition = format!("__fish_upt_using_subcommand {first}");
                for sub in rest {
                    condition += &format!("; and __fish_seen_subcommand_from {sub}");
                }
                condition
            }
        };
        out.push_str(&format!(
            "complete -c upt -n \"{condition}\" -f -a \"{}\"\n",
            values.join(" ")
        ));
    }
    for sub in command.get_subcommands() {
        path.push(sub.get_name());
        fish_collect(sub, path, out);
        path.pop();
    }
}

/// The whole `upt` command line as one clap [`Command`]: the global options
/// handled by `main::Cli::parse`, and every built-in as a subcommand.
pub fn cli_command() -> Command {
    let mut command = Command::new("upt")
        .about(env!("CARGO_PKG_DESCRIPTION"))
        .version(env!("CARGO_PKG_VERSION"))
        .subcommand_required(true)
        // `help` is a real built-in here, not clap's generated one.
        .disable_help_subcommand(true)
        .arg(
            Arg::new("color")
                .long("color")
                .value_name("WHEN")
                .value_parser(["always", "never", "auto"])
                .help("When to use color"),
        )
        .arg(
            Arg::new("config")
                .long("config")
                .value_name("FILE")
                .value_hint(ValueHint::FilePath)
                .action(ArgAction::Set)
                .help("Use an alternate config file"),
        );
    for builtin in commands::BUILTINS {
        command = command.subcommand((builtin.command)().about(builtin.summary));
    }
    command.build();
    command
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn every_builtin_command_is_named_after_it() {
        for builtin in commands::BUILTINS {
            assert_eq!((builtin.command)().get_name(), builtin.name);
        }
    }

    #[test]
    fn cli_command_is_valid() {
        // `debug_assert` catches clap definition mistakes (duplicate flags,
        // bad positional layouts, ...) in every subcommand.
        cli_command().debug_assert();
    }

    #[test]
    fn every_shell_gets_a_script() {
        for shell in [
            Shell::Zsh,
            Shell::Bash,
            Shell::Fish,
            Shell::PowerShell,
            Shell::Elvish,
        ] {
            assert!(!script(shell).is_empty(), "{shell}");
        }
    }
}
